const generatedHeader = '// Generated by scripts/build-component.mjs from Jco output. Do not edit.\n\n'

/** Generates the shared asset list and literal browser URLs so bundlers can discover every core module. */
export function componentAssetSources(coreModules: string[]) {
  return {
    'componentModules.ts': `${generatedHeader}/** Core module assets generated by Jco's explicit component instantiation mode. */
export const COMPONENT_MODULE_NAMES = ${JSON.stringify(coreModules)} as const
`,
    'loadModule.browser.ts': `/// <reference lib="dom" />
${generatedHeader}import { COMPONENT_MODULE_NAMES } from './componentModules.js'
import type { ComponentModules } from './host.js'

/** Loads every core module needed to instantiate the bundled component. */
export async function loadModule(): Promise<ComponentModules> {
  const modules = await Promise.all([
${coreModules.map((name) => `    WebAssembly.compileStreaming(fetch(new URL(${JSON.stringify(`./component/${name}`)}, import.meta.url))),`).join('\n')}
  ])
  return Object.fromEntries(COMPONENT_MODULE_NAMES.map((name, index) => [name, modules[index]]))
}
`,
  }
}
